<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api, errorMessage } from '../services/api'
import { useFeedbackStore } from '../stores/feedback'
const router=useRouter(),feedback=useFeedbackStore();const draft=ref(null),users=ref([]),products=ref([]),customerQ=ref(''),productQ=ref(''),selectedCustomer=ref(null),productDialog=ref(false),selectedProduct=ref(null),color=ref(''),size=ref(''),quantity=ref(1),notes=ref(''),submitting=ref(false)
const customerItems=computed(()=>users.value.filter(u=>u.role==='client'&&u.active&&(!customerQ.value||`${u.fullName} ${u.companyName} ${u.username}`.toLowerCase().includes(customerQ.value.toLowerCase()))));const productItems=computed(()=>{const query=productQ.value.trim().toLowerCase();return products.value.filter(p=>p.active&&(!query||`${p.name} ${p.ref}`.toLowerCase().includes(query))).sort((a,b)=>query&&String(a.ref).toLowerCase().startsWith(query)!==String(b.ref).toLowerCase().startsWith(query)?(String(a.ref).toLowerCase().startsWith(query)?-1:1):a.name.localeCompare(b.name))})
async function load(){try{const [d,u,p]=await Promise.all([api.get('/admin/order-draft'),api.get('/admin/users'),api.get('/admin/catalog')]);draft.value=d.data.draft;users.value=u.data.users;products.value=p.data.products;selectedCustomer.value=draft.value.customer_user_id;notes.value=draft.value.notes||''}catch(e){feedback.show(errorMessage(e),'error')}}
async function setCustomer(id){try{draft.value=(await api.patch('/admin/order-draft/customer',{customer_id:id})).data.draft;feedback.show('Cliente selecionado.')}catch(e){feedback.show(errorMessage(e),'error')}}
function chooseProduct(p){selectedProduct.value=p;color.value=p.colors[0]||'';size.value=p.sizes[0]||'';quantity.value=p.quantityStep;productDialog.value=true}
async function add(){try{draft.value=(await api.post('/admin/order-draft/lines',{ref:selectedProduct.value.ref,color:color.value,size:size.value,quantity:quantity.value})).data.draft;productDialog.value=false;feedback.show('Produto adicionado.')}catch(e){feedback.show(errorMessage(e),'error')}}
async function remove(line){try{draft.value=(await api.delete(`/admin/order-draft/lines/${line.line_id}`)).data.draft}catch(e){feedback.show(errorMessage(e),'error')}}
async function saveNotes(){try{draft.value=(await api.patch('/admin/order-draft/notes',{notes:notes.value})).data.draft;feedback.show('Notas guardadas.')}catch(e){feedback.show(errorMessage(e),'error')}}
async function clearDraft(){if(!await feedback.confirm('Limpar o cliente, os produtos e as notas desta encomenda?','Limpar rascunho'))return;try{draft.value=(await api.delete('/admin/order-draft')).data.draft;selectedCustomer.value=null;notes.value='';feedback.show('Rascunho limpo.')}catch(e){feedback.show(errorMessage(e),'error')}}
async function submit(){if(!await feedback.confirm('Criar esta encomenda para o cliente selecionado?','Criar encomenda'))return;submitting.value=true;try{const {data}=await api.post('/admin/order-draft/submit');feedback.show('Encomenda criada.');router.push(`/admin/encomendas/${data.order.publicNumber}`)}catch(e){feedback.show(errorMessage(e),'error')}finally{submitting.value=false}}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h1>Nova encomenda</h1><p>Crie uma encomenda em nome de um cliente.</p></div><v-btn variant="tonal" color="error" prepend-icon="mdi-delete-sweep-outline" @click="clearDraft">Limpar rascunho</v-btn></div><v-skeleton-loader v-if="!draft" type="article, article"/><v-row v-else><v-col cols="12" lg="5"><v-card class="soft-card pa-5 mb-5"><div class="text-h6 font-weight-bold mb-4">1. Selecionar cliente</div><v-autocomplete v-model="selectedCustomer" v-model:search="customerQ" label="Pesquisar cliente" :items="customerItems" item-title="fullName" item-value="id" @update:model-value="setCustomer"><template #item="{props,item}"><v-list-item v-bind="props" :subtitle="item.raw.companyName||item.raw.username"/></template></v-autocomplete><v-alert v-if="draft.customer_user_id" type="success" variant="tonal"><b>{{draft.customer_name}}</b><div>{{draft.customer_company}}</div></v-alert></v-card><v-card class="soft-card pa-5"><div class="text-h6 font-weight-bold mb-4">2. Adicionar produtos</div><v-text-field v-model="productQ" clearable label="Pesquisar por nome ou referência" hint="Ex.: meia ou 2145" persistent-hint prepend-inner-icon="mdi-magnify"/><v-list max-height="430" class="overflow-y-auto"><v-list-item v-for="p in productItems.slice(0,30)" :key="p.ref" :title="p.name" :subtitle="`${p.ref} · ${Number(p.price).toFixed(2)} €`" append-icon="mdi-plus-circle-outline" @click="chooseProduct(p)"/></v-list></v-card></v-col><v-col cols="12" lg="7"><v-card class="soft-card pa-5"><div class="text-h6 font-weight-bold mb-4">Resumo</div><v-table v-if="draft.lines.length"><thead><tr><th>Produto</th><th>Variante</th><th>Qtd.</th><th class="text-right">Total</th><th></th></tr></thead><tbody><tr v-for="line in draft.lines" :key="line.line_id"><td><b>{{line.product_name}}</b><div class="text-caption">{{line.product_ref}}</div></td><td>{{[line.color,line.size].filter(Boolean).join(' · ')||'—'}}</td><td>{{line.quantity}}</td><td class="text-right">{{Number(line.line_total).toFixed(2)}} €</td><td><v-btn icon="mdi-delete-outline" variant="text" color="error" @click="remove(line)"/></td></tr></tbody></v-table><div v-else class="empty-state">Ainda não adicionou produtos.</div><v-divider class="my-5"/><v-textarea v-model="notes" label="Notas" rows="3" @blur="saveNotes"/><div class="d-flex justify-space-between text-h6 mb-5"><span>Total</span><b>{{Number(draft.subtotal).toFixed(2)}} €</b></div><v-btn block size="large" color="primary" :disabled="!draft.customer_user_id||!draft.lines.length" :loading="submitting" @click="submit">Criar encomenda</v-btn></v-card></v-col></v-row>
  <v-dialog v-model="productDialog" max-width="500"><v-card v-if="selectedProduct"><v-card-title class="pa-6 pb-2">{{selectedProduct.name}}</v-card-title><v-card-text class="pa-6"><v-select v-if="selectedProduct.colors.length" v-model="color" label="Cor" :items="selectedProduct.colors"/><v-select v-if="selectedProduct.sizes.length" v-model="size" label="Tamanho" :items="selectedProduct.sizes"/><v-text-field v-model.number="quantity" type="number" label="Quantidade" :step="selectedProduct.quantityStep" :min="selectedProduct.quantityStep"/></v-card-text><v-card-actions class="px-6 pb-6"><v-spacer/><v-btn variant="text" @click="productDialog=false">Cancelar</v-btn><v-btn color="primary" @click="add">Adicionar</v-btn></v-card-actions></v-card></v-dialog>
</div></template>
